    crumb="Оплата проезда",
    tile=("Оплата проезда", "Дмей несиот: до " + S["CAP"] + " ₪ в день, кому положено и как считают"),
    title="Оплата проезда на работу в Израиле 2026: дмей несиот до " + S["CAP"] + " ₪",
    desc="Дмей несиот в 2026 году: наниматель возмещает проезд до " + S["CAP"] + " ₪ за рабочий день. Кому положено, как считают сумму, подвозка и что проверить в тлуше.",
