# ─────────────────────────── ЧАЕВЫЕ ───────────────────────────
# Источники (10.11.2026): kolzchut «תשר ("טיפ") למלצרים במסעדות, בתי קפה וברים» (обновлено 17.08.2026, через браузер);
#   efraty.com «הכנסה מתשר (טיפ) כהכנסת המעסיק…» (04.02.2019) — пересказ решения Национального суда по труду
#   по делам Кис и Буда (עב"ל 44405-10-15, ע"ע 28480-02-16) от 26.03.2018, вступило в силу 01.01.2019; циркуляр БЛ.
# Подтверждено двумя источниками: чаевые в ресторанах, кафе, барах (и пабах) = зарплата, даже если не прошли через кассу;
#   с 01.01.2019; налог, БЛ, пенсия — с суммы вместе с чаевыми, доля нанимателя тоже; по умолчанию чаевыми нельзя
#   оплачивать долю нанимателя в БЛ/пенсии и соц. выплаты — только при иной договорённости (kolzchut: письменное
#   согласие + излишек сверх обещанной зарплаты); в любом случае не меньше минимальной (или договорной, что выше);
#   пособия БЛ считаются по полной зарплате с чаевыми; решение касается только общепита — залы торжеств исключены
#   (kolzchut: в залах чаевые не зарплата; efraty: решение только про рестораны, кафе, бары, пабы).
# ❗Это решение суда по труду, а не БАГАЦ и не поправка закона (в очереди было «БАГАЦ/кодекс»); НДС на чаевые не пишем;
#   проезд и оздоровительные из чаевых — только kolzchut, пишем вместе с общим правилом (efraty: «соц. выплаты»).
_TIP_H = 6
_TIP_MIN = rates["min_hour"] * _TIP_H
_TIP_ROWS = (150.0, 200.0, _TIP_MIN, 400.0)
def _tipr(t):
    add = max(0.0, _TIP_MIN - t)
    return "<tr><td>%s ₪</td><td>%s ₪</td><td>%s</td><td>%s ₪</td></tr>" % (
        money(t, 2), money(_TIP_MIN, 2), (money(add, 2) + " ₪") if add > 0.005 else "0", money(t + add, 2))
TIP = {
    "MINH": ("%.2f" % rates["min_hour"]).replace(".", ","),
    "H": str(_TIP_H),
    "SHIFT": money(_TIP_MIN, 2),
    "ROWS": "\n".join(_tipr(t) for t in _TIP_ROWS),
    "BOT": BOT,
}

TIP_BODY = """
<h2>Чаевые — это зарплата</h2>
<p>В ресторанах, кафе, барах и пабах чаевые (тип, на иврите <b>תשר</b>) по израильскому праву — не подарок официанту, а часть его зарплаты. Так решил Национальный суд по труду в марте 2018 года по делам Кис и Буда, и новый порядок действует с <b>1 января 2019 года</b>. Чаевые считаются доходом заведения: официант передаёт их нанимателю, тот проводит их через кассу и выплачивает работнику через тлуш.</p>
<p>Правило работает, даже если чаевые оставили наличными и никто их не записал. Касается оно не только официантов, а всей «цепочки обслуживания», которая по обычаю заведения делит чаевые: барменов, работников кухни и других.</p>
<p>Исключение — <b>залы и сады торжеств</b>. Там чаевые зарплатой не считаются, их не передают нанимателю и не платят с них налог, Битуах Леуми и пенсию. Всё, что ниже, относится к общепиту.</p>

<h2>Минимальная зарплата и доплата нанимателя</h2>
<p>Сколько бы ни было чаевых, итог за час — чаевые или чаевые плюс ставка — не может быть ниже <a href="/prava/minimalnaya-zarplata/">минимальной зарплаты</a>: <b>{MINH} ₪ в час</b> в 2026 году. Если по договору обещано больше минимума, то не ниже договорной суммы. Не хватает — разницу наниматель доплачивает из своего кармана и платит с неё положенные взносы.</p>
<p>Что именно добавлять, зависит от договорённости до начала работы. Если договорились «ставка плюс чаевые» — наниматель платит ставку сверху. Если договорились «доплачу до такой-то суммы» — он доплачивает только тогда, когда чаевых меньше этой суммы. Пример для смены из {H} часов по минимальной ставке — это <b>{SHIFT} ₪</b>:</p>
<div class="tblwrap"><table>
<tr><th>Чаевых за смену</th><th>Минимум за {H} часов</th><th>Доплата нанимателя</th><th>Итого брутто</th></tr>
{ROWS}
</table></div>
<p>Если чаевых больше минимума, вернуть разницу нанимателю официант не обязан. Цифры — брутто: налог, Битуах Леуми и пенсию удерживают уже со всей суммы.</p>

<h2>Налог, Битуах Леуми и пенсия</h2>
<p>Раз чаевые — зарплата, все удержания считаются с суммы вместе с ними: подоходный налог, Битуах Леуми и мас бриют, доля работника в <a href="/prava/pensiya/">пенсии</a>. Наниматель тоже платит свою часть в Битуах Леуми и пенсию с полной суммы. Зато и накопления в пенсионном фонде растут быстрее, а значит, выше будут будущая пенсия и страховые выплаты фонда при инвалидности или потере кормильца.</p>
<p>По умолчанию наниматель может тратить чаевые только на саму зарплату обслуживающего персонала. Оплачивать из них свою долю в Битуах Леуми и пенсии, <a href="/prava/nesiot/">проезд</a>, <a href="/prava/havraa/">оздоровительные</a> или другие социальные выплаты нельзя. Исключение — если работник письменно согласился и чаевые превышают обещанную ему зарплату, то есть есть излишек.</p>

<h2>Отпуск, больничные, пицуим и пособия</h2>
<p>Всё, что считается от зарплаты, считается вместе с чаевыми. Наниматель платит по полной зарплате за <a href="/prava/otpusk/">отпуск</a>, больничные и пицуим. Битуах Леуми по полной зарплате считает пособие по безработице, родовые, оплату милуим и другие выплаты, которые заменяют доход.</p>
<p>Право на это есть, даже если наниматель не провёл чаевые через тлуш и не заплатил с них взносы, — платить их должен был не работник. Но на практике тогда трудно доказать, сколько вы получали: без строки в тлуше спор может дойти до суда. Поэтому лучше с первого месяца требовать, чтобы чаевые были в листке.</p>

<h2>Если чаевых нет в тлуше</h2>
<p>Обратитесь к нанимателю и попросите провести чаевые через расчётный листок, лучше письменно. Сохраняйте свои записи: даты смен, суммы чаевых, переписку, фото графика. Если наниматель отказывается, можно пожаловаться в отдел надзора министерства труда (*2570) или обратиться в суд по труду. Конкретную ситуацию лучше разобрать с юристом или профсоюзом.</p>

<div class="note"><b>Что проверить в тлуше:</b> есть ли отдельная строка чаевых — <b>תשר</b> или <b>טיפים</b>; дотягивает ли брутто хотя бы до {MINH} ₪ × отработанные часы — если нет, должна быть доплата (<b>השלמה לשכר מינימום</b>); удержаны ли пенсия и Битуах Леуми со всей суммы, включая чаевые; нет ли вычета из чаевых «на взносы нанимателя» или «на проезд» без вашего письменного согласия. Фото листка можно прислать боту <a href="{BOT}">@TlushScanBot</a>, он разберёт строки по порядку.</div>

<h2>Смежные темы</h2>
<ul>
<li><a href="/prava/minimalnaya-zarplata/">Минимальная зарплата 2026</a></li>
<li><a href="/prava/tlush/">Как читать тлуш: строка за строкой</a></li>
<li><a href="/prava/pensiya/">Пенсионные отчисления</a></li>
<li><a href="/prava/uderzhaniya/">Что нельзя удерживать из зарплаты</a></li>
<li><a href="/prava/avtala/">Пособие по безработице</a></li>
</ul>
"""
for _k, _v in TIP.items():
    TIP_BODY = TIP_BODY.replace("{" + _k + "}", _v)

PAGES.append(dict(
    slug="chaevye",
    crumb="Чаевые",
    tile=("Чаевые", "часть зарплаты с 2019: минимум {MINH} ₪ в час, пенсия и Битуах Леуми с чаевыми, залы торжеств — исключение".replace("{MINH}", TIP["MINH"])),
    title="Чаевые в Израиле 2026: часть зарплаты, пенсия и минимум",
    desc="Чаевые официанта в Израиле — часть зарплаты с 2019 года: доплата до минимума {MINH} ₪ в час, пенсия и Битуах Леуми с чаевых, что видно в тлуше.".replace("{MINH}", TIP["MINH"]),
    h1="Чаевые: часть зарплаты с 2019, пенсия и минимум",
    lead="С 2019 года чаевые в ресторанах, кафе и барах Израиля считаются зарплатой: они должны проходить через тлуш, с них платят пенсию и Битуах Леуми, а итог не может быть ниже минимальной ставки. Разбираем, кто доплачивает, на что нельзя тратить чаевые и что проверить в листке.",
    body=TIP_BODY,
    faq=[
        ("Чаевые — это часть зарплаты?",
         "Да, в ресторанах, кафе, барах и пабах. По решению Национального суда по труду с 1 января 2019 года чаевые считаются доходом заведения и зарплатой обслуживающего персонала, даже если их оставили наличными и не записали. В залах и садах торжеств действует другое правило — там чаевые зарплатой не считаются."),
        ("Обязан ли наниматель доплатить, если чаевых мало?",
         "Да. Итог за час — чаевые или ставка плюс чаевые — не может быть ниже минимальной зарплаты, в 2026 году это {MINH} ₪ в час, или договорной ставки, если она выше. Разницу наниматель платит из своих денег и платит с неё взносы.".replace("{MINH}", TIP["MINH"])),
        ("Может ли наниматель платить из чаевых пенсию, проезд или оздоровительные?",
         "По умолчанию нет: чаевые идут только на зарплату. Свою долю в пенсии и Битуах Леуми, проезд и оздоровительные наниматель платит сверху. Исключение возможно, только если работник дал письменное согласие и чаевых больше, чем обещанная зарплата."),
        ("Что делать, если чаевых нет в тлуше?",
         "Письменно попросить нанимателя провести их через расчётный листок и вести свои записи по сменам и суммам. Права на пенсию, отпуск и пособия с чаевых сохраняются, но без строки в тлуше их сложнее доказать. Если наниматель отказывается — жалоба в надзор министерства труда (*2570) или суд по труду."),
    ]))

# ─────────────────────────── сборка ───────────────────────────
def write(path, text):
    full = os.path.join(ROOT, path)
    d = os.path.dirname(full)
    if d and not os.path.isdir(d):
        os.makedirs(d)
    io.open(full, "w", encoding="utf-8", newline="\n").write(text)
    print("written:", path)

LASTMOD = os.path.join(ROOT, "tools", "prava_lastmod.json")
UPD_MARK = "@@UPDATED@@"

def ru_date(iso):
    d = datetime.date.fromisoformat(iso)
    return "%d %s %d" % (d.day, RU_MONTH[d.month-1], d.year)

def stamp(state, key, html):
    """дата последнего НАСТОЯЩЕГО изменения страницы: хэш без даты проверки в подвале"""
    import hashlib
    h = hashlib.sha1(html.encode("utf-8")).hexdigest()
    old = state.get(key)
    if not old or old["hash"] != h:
        state[key] = {"hash": h, "date": datetime.date.today().isoformat()}
    return state[key]["date"]

def related_html(cur):
    links = "\n".join('<li><a href="/prava/%s/">%s</a></li>' % (p["slug"], p["tile"][0]) for p in PAGES if p["slug"] != cur)
    return '<h2>Ещё в справочнике</h2>\n<ul class="rel">\n%s\n</ul>' % links

def build():
    import json
    state = json.load(io.open(LASTMOD, encoding="utf-8")) if os.path.exists(LASTMOD) else {}
    for p in PAGES:
        html = page(p["slug"], p["title"], p["desc"], p["h1"], p["lead"], p["body"], p["faq"], p["crumb"],
                    related=related_html(p["slug"]), updated=UPD_MARK)
        d = stamp(state, p["slug"], html)
        write("prava/%s/index.html" % p["slug"], html.replace(UPD_MARK, ru_date(d)))

    tiles = "\n".join(
        '<a class="tile" href="/prava/%s/"><b>%s</b><span>%s</span></a>' % (p["slug"], p["tile"][0], p["tile"][1])
        for p in PAGES)
    hub_body = """
<p>Здесь мы простыми словами объясняем права работника в Израиле и показываем, где именно эти деньги видно в расчётном листке. Каждую цифру сверяем с официальными источниками и указываем дату проверки.</p>
<div class="grid">
{TILES}
</div>
<h2>С чего начать</h2>
<p>Если не знаете, с какой стороны подойти к своему тлушу, начните с двух вещей. Посчитайте свои часы за неделю и сравните со строками 100 %, 125 % и 150 %. Затем посмотрите строку остатка отпуска: она показывает, копятся ли ваши дни.</p>
<p>Минимальная зарплата в 2026 году — {MIN_MONTH} ₪ в месяц при полной ставке и {MIN_HOUR} ₪ в час. Дмей авраа в частном секторе — {HAVRAA} ₪ за день.</p>
""".replace("{TILES}", tiles).replace("{MIN_MONTH}", MIN_MONTH).replace("{MIN_HOUR}", MIN_HOUR).replace("{HAVRAA}", HAVRAA)
    hub = page("", "Права работника в Израиле: короткий справочник — Хешбон+",
               "Права работника в Израиле простыми словами: пицуим, отпуск, больничные, сверхурочные. Цифры 2026 года и то, как проверить их в своём тлуше.",
               "Права работника в Израиле", "Короткий справочник по деньгам: что положено по закону и как увидеть это в расчётном листке.",
               hub_body, [], "", updated=UPD_MARK)
    hub_date = stamp(state, "_hub", hub)
    write("prava/index.html", hub.replace(UPD_MARK, ru_date(hub_date)))

    # главная: прямые ссылки на все статьи справочника (самая сильная страница сайта передаёт им вес)
    home_path = os.path.join(ROOT, "index.html")
    home = io.open(home_path, encoding="utf-8").read()
    A, B = "<!--PRAVA-LINKS-START-->", "<!--PRAVA-LINKS-END-->"
    block = (A + '\n  <div class="disclaimer" id="pravaLinks" style="padding-top:0">Справочник прав работника: '
             + " · ".join('<a href="https://heshbonplus.com/prava/%s/">%s</a>' % (p["slug"], p["tile"][0]) for p in PAGES)
             + '</div>\n  ' + B)
    if A in home:
        home = home[:home.index(A)] + block + home[home.index(B) + len(B):]
    else:
        anchor = '<div class="disclaimer" id="copyright"'
        k = home.index(anchor)
        k = home.index("</div>", k) + len("</div>")
        home = home[:k] + "\n  " + block + home[k:]
    io.open(home_path, "w", encoding="utf-8", newline="\n").write(home)
    home_date = stamp(state, "_home", home)
    print("written: index.html (ссылки на справочник)")

    lm = {"/": home_date, "/prava/": hub_date}
    lm.update({"/prava/%s/" % p["slug"]: state[p["slug"]]["date"] for p in PAGES})
    urls = [("/", "1.0"), ("/prava/", "0.9")] + [("/prava/%s/" % p["slug"], "0.8") for p in PAGES] + \
           [("/terms.html", "0.3"), ("/privacy.html", "0.3")]
    sm = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
    for u, pr in urls:
        d = lm.get(u)
        sm += ("  <url><loc>%s%s</loc>%s<priority>%s</priority></url>\n"
               % (SITE, u, "<lastmod>%s</lastmod>" % d if d else "", pr))
    sm += "</urlset>\n"
    write("sitemap.xml", sm)
    write("robots.txt", "User-agent: *\nAllow: /\n\nSitemap: %s/sitemap.xml\n" % SITE)
    io.open(LASTMOD, "w", encoding="utf-8").write(json.dumps(state, ensure_ascii=False, indent=1))


if __name__ == "__main__":
    build()
